export class FakePaymentProvider extends Context.Tag('test/FakePaymentProvider')<FakePaymentProvider, FakePaymentProvider.Service>() {}
// Service extends PaymentProvider.Service with declineNext, chargesMade
const testLayer = Layer.provideMerge(Layer.mergeAll(Reservations.Default, Rooms.Default), Layer.mergeAll(FakePaymentProviderLayer, TestStore))

const testLayer = Layer.provideMerge(Layer.mergeAll(Reservations.Default, Rooms.Default), Layer.mergeAll(Layer.succeed(HotelConfig, { maxNights: 14 }), TestStore))
When('Grace reserves fifteen nights')('result', ({ reservations }) => reservations.execute(new Reserve({ guest: GRACE, kind: 'double', nights: 15 })).pipe(Effect.either)),
Then('she is told the stay is too long')(({ result }, expect) => expect(result).toMatchObject(Either.left({ _tag: 'StayTooLong', maxNights: 14 }))),

// FakeMailer runs in the Mailer port's contract suite beside the real adapter
When('Grace reserves a double room')('result', ({ reservations }) => reservations.execute(new Reserve({ guest: GRACE, kind: 'double' }))),
Then('Grace is sent her confirmation')(({ mailer }, expect) => Effect.flatMap(mailer.sent, (sent) => expect(sent).toEqual([{ to: GRACE.email, kind: 'confirmation' }]))),
